ROOT = os.path.dirname(os.path.abspath(__file__))
P = os.path.join(ROOT, 'akty-data.json')
D = json.load(open(P, encoding='utf-8'))
for d in D:
    tr = T[d['id']]
    d['translation'] = ''.join('<p class="ak-ptitle">%s</p>' % html.escape(p[1:].strip()) if p.startswith('~') else '<p>%s</p>' % html.escape(p) for p in tr)
    for a, b in FIX.items():
        for k in ('persons', 'placesIdx'):
            d[k] = d[k].replace(a, b)
    if d['id'] in PLACES: d['places'] = PLACES[d['id']]
    if d['id'] in SUMMARY: d['summary'] = SUMMARY[d['id']]
json.dump(D, open(P, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('ok', len(D))
